package toml

import (
	"errors"
	"strings"
	"testing"
)

func TestDecodeStubReportsNotImplemented(t *testing.T) {
	tests := []struct {
		name  string
		input string
	}{
		{name: "empty", input: ""},
		{name: "single key", input: "key = 1\n"},
		{name: "table", input: "[table]\nkey = \"v\"\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			doc, err := Decode(strings.NewReader(tt.input))
			if !errors.Is(err, ErrNotImplemented) {
				t.Fatalf("Decode(%q) error = %v, want %v", tt.input, err, ErrNotImplemented)
			}
			if doc != nil {
				t.Errorf("Decode(%q) = %v, want nil document", tt.input, doc)
			}
		})
	}
}

